/* The external scanner of the cartan grammar, generated by treegram
 * from the grammar value that also prints grammar.js. Do not edit. */

#include "tree_sitter/parser.h"

enum TokenType {
  NEWLINE,
  NO_OPERAND,
  BARE_OPERAND,
  ERROR_SENTINEL,
};

static void skip(TSLexer *lexer) { lexer->advance(lexer, true); }

static void step(TSLexer *lexer) { lexer->advance(lexer, false); }

static bool is_space(int32_t c) { return c == 32 || c == 9 || c == 13; }

static bool is_word_start(int32_t c) { return c == 95 || (c >= 65 && c <= 90) || (c >= 97 && c <= 122); }

static bool is_word_part(int32_t c) { return c == 95 || (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || (c >= 48 && c <= 57); }

typedef struct {
  int32_t first;
  bool spaced;
  bool word;
  int keyword;
  int literal;
} Next;

static const char *const KEYWORDS[] = {
  "and",
  "as",
  "but",
  "each",
  "else",
  "false",
  "fiber",
  "fold",
  "for",
  "if",
  "in",
  "locked",
  "match",
  "module",
  "namespace",
  "none",
  "not",
  "of",
  "or",
  "param",
  "periodic",
  "reduce",
  "require",
  "state",
  "step",
  "struct",
  "tap",
  "texture",
  "then",
  "true",
  "use",
  "when",
  "while",
  "with",
  0,
};

/* The keyword the word is, numbered from 1, or 0 for a name. */
static int keyword(const char *word) {
  for (int i = 0; KEYWORDS[i]; i++) {
    const char *k = KEYWORDS[i];
    int j = 0;
    while (k[j] && k[j] == word[j]) j++;
    if (!k[j] && !word[j]) return i + 1;
  }
  return 0;
}

/* The longest literal at the lexer, numbered from 1, or 0. */
static int literal(TSLexer *lexer) {
  int found = 0;
  switch (lexer->lookahead) {
    case 33:
      step(lexer);
      switch (lexer->lookahead) {
        case 61:
          step(lexer);
          found = 1;
          break;
      }
      break;
    case 34:
      step(lexer);
      found = 2;
      switch (lexer->lookahead) {
        case 34:
          step(lexer);
          switch (lexer->lookahead) {
            case 34:
              step(lexer);
              found = 3;
              break;
          }
          break;
      }
      break;
    case 40:
      step(lexer);
      found = 4;
      break;
    case 41:
      step(lexer);
      found = 5;
      break;
    case 42:
      step(lexer);
      found = 6;
      break;
    case 43:
      step(lexer);
      found = 7;
      break;
    case 44:
      step(lexer);
      found = 8;
      break;
    case 45:
      step(lexer);
      found = 9;
      switch (lexer->lookahead) {
        case 62:
          step(lexer);
          found = 10;
          break;
      }
      break;
    case 46:
      step(lexer);
      found = 11;
      switch (lexer->lookahead) {
        case 46:
          step(lexer);
          found = 12;
          switch (lexer->lookahead) {
            case 61:
              step(lexer);
              found = 13;
              break;
          }
          break;
      }
      break;
    case 47:
      step(lexer);
      found = 14;
      switch (lexer->lookahead) {
        case 47:
          step(lexer);
          found = 15;
          break;
      }
      break;
    case 58:
      step(lexer);
      found = 16;
      switch (lexer->lookahead) {
        case 58:
          step(lexer);
          found = 17;
          break;
        case 61:
          step(lexer);
          found = 18;
          break;
      }
      break;
    case 59:
      step(lexer);
      found = 19;
      break;
    case 60:
      step(lexer);
      found = 20;
      switch (lexer->lookahead) {
        case 45:
          step(lexer);
          found = 21;
          break;
        case 61:
          step(lexer);
          found = 22;
          break;
        case 62:
          step(lexer);
          found = 23;
          break;
      }
      break;
    case 61:
      step(lexer);
      found = 24;
      switch (lexer->lookahead) {
        case 61:
          step(lexer);
          found = 25;
          break;
        case 62:
          step(lexer);
          found = 26;
          break;
      }
      break;
    case 62:
      step(lexer);
      found = 27;
      switch (lexer->lookahead) {
        case 61:
          step(lexer);
          found = 28;
          break;
      }
      break;
    case 63:
      step(lexer);
      found = 29;
      switch (lexer->lookahead) {
        case 63:
          step(lexer);
          found = 30;
          break;
      }
      break;
    case 64:
      step(lexer);
      found = 31;
      break;
    case 91:
      step(lexer);
      found = 32;
      break;
    case 93:
      step(lexer);
      found = 33;
      break;
    case 94:
      step(lexer);
      found = 34;
      break;
    case 123:
      step(lexer);
      found = 35;
      break;
    case 124:
      step(lexer);
      found = 36;
      break;
    case 125:
      step(lexer);
      found = 37;
      break;
  }
  return found;
}

/* The keyword the word at the lexer is, numbered from 1, or 0 for a
 * name; the lexer stands after the word. */
static int read_word(TSLexer *lexer) {
  char word[32];
  unsigned n = 0;
  while (is_word_part(lexer->lookahead) || (n == 0 && is_word_start(lexer->lookahead))) {
    if (n < sizeof word - 1) word[n] = (char)lexer->lookahead;
    n++;
    step(lexer);
  }
  if (n >= sizeof word) return 0;
  word[n] = 0;
  return keyword(word);
}

static Next next_token(TSLexer *lexer, bool spaced) {
  Next next = {lexer->lookahead, spaced, false, 0, 0};
  if (is_word_start(lexer->lookahead)) {
    next.word = true;
    next.keyword = read_word(lexer);
  } else {
    next.literal = literal(lexer);
  }
  return next;
}

/* Whether the line at the lexer opens with an operator that continues
 * the line above. */
static bool continues_line(TSLexer *lexer) {
  if (is_word_start(lexer->lookahead)) {
    switch (read_word(lexer)) {
      case 5:
        return lexer->lookahead == 32 || lexer->lookahead == 9 || lexer->lookahead == 13 || lexer->lookahead == 10;
      case 19:
        return lexer->lookahead == 32 || lexer->lookahead == 9 || lexer->lookahead == 13 || lexer->lookahead == 10;
      case 1:
        return lexer->lookahead == 32 || lexer->lookahead == 9 || lexer->lookahead == 13 || lexer->lookahead == 10;
      case 34:
        return lexer->lookahead == 32 || lexer->lookahead == 9 || lexer->lookahead == 13 || lexer->lookahead == 10;
      case 3:
        return lexer->lookahead == 32 || lexer->lookahead == 9 || lexer->lookahead == 13 || lexer->lookahead == 10;
      default:
        return false;
    }
  }
  switch (literal(lexer)) {
    case 25:
    case 1:
    case 22:
    case 28:
    case 20:
    case 27:
    case 30:
    case 7:
    case 23:
    case 6:
    case 15:
    case 14:
    case 31:
    case 34:
    case 16:
    case 11:
    case 26:
      return true;
  }
  return false;
}

static bool begins_expression(Next next) {
  if (next.word) {
    switch (next.keyword) {
    case 4:
    case 6:
    case 8:
    case 9:
    case 10:
    case 12:
    case 13:
    case 16:
    case 17:
    case 21:
    case 22:
    case 27:
    case 28:
    case 30:
      return true;
    case 0:
      return true;
    default:
      return false;
    }
  }
  switch (next.literal) {
    case 3:
    case 4:
    case 7:
    case 9:
    case 12:
    case 13:
    case 16:
    case 32:
    case 35:
      if (true) return true;
  }
  return ((next.first >= 48 && next.first <= 57) ||
         next.first == 34);
}

static bool holds_no_operand(Next next) {
  return !begins_expression(next) || (!next.word && next.literal == 35);
}

static bool continues_expression(Next next) {
  if (next.word) {
    switch (next.keyword) {
    case 1:
    case 3:
    case 19:
    case 21:
    case 34:
      return true;
    case 0:
      return false;
    default:
      return false;
    }
  }
  switch (next.literal) {
    case 1:
    case 6:
    case 7:
    case 9:
    case 11:
    case 12:
    case 13:
    case 14:
    case 15:
    case 16:
    case 20:
    case 22:
    case 23:
    case 25:
    case 27:
    case 28:
    case 29:
    case 30:
    case 31:
    case 32:
    case 34:
    case 35:
      if (true) return true;
  }
  return false;
}

static bool abuts_expression(Next next) {
  if (next.word) {
    switch (next.keyword) {
    case 0:
      return !next.spaced && false;
    default:
      return false;
    }
  }
  return false;
}

static bool holds_bare_operand(Next next) {
  return begins_expression(next) && !continues_expression(next) && !abuts_expression(next) && !((!next.word && next.literal == 4) || (!next.word && next.literal == 32) || (!next.word && next.literal == 35));
}

void *tree_sitter_cartan_external_scanner_create(void) { return NULL; }

void tree_sitter_cartan_external_scanner_destroy(void *payload) { (void)payload; }

unsigned tree_sitter_cartan_external_scanner_serialize(void *payload, char *buffer) {
  (void)payload;
  (void)buffer;
  return 0;
}

void tree_sitter_cartan_external_scanner_deserialize(void *payload, const char *buffer,
                                                     unsigned length) {
  (void)payload;
  (void)buffer;
  (void)length;
}

bool tree_sitter_cartan_external_scanner_scan(void *payload, TSLexer *lexer,
                                              const bool *valid_symbols) {
  (void)payload;
  bool recovering = valid_symbols[ERROR_SENTINEL];
  bool spaced = false;
  while (is_space(lexer->lookahead)) {
    skip(lexer);
    spaced = true;
  }
  if (valid_symbols[NEWLINE] && lexer->lookahead == '\n') {
    step(lexer);
    lexer->mark_end(lexer);
    lexer->result_symbol = NEWLINE;
    while (is_space(lexer->lookahead) || lexer->lookahead == '\n') step(lexer);
    if (lexer->eof(lexer)) return false;
    return !continues_line(lexer);
  }
  if (recovering || !(valid_symbols[NO_OPERAND] || valid_symbols[BARE_OPERAND])) return false;
  lexer->mark_end(lexer);
  Next next = next_token(lexer, spaced);
  if (valid_symbols[NO_OPERAND] && holds_no_operand(next)) {
    lexer->result_symbol = NO_OPERAND;
    return true;
  }
  if (valid_symbols[BARE_OPERAND] && holds_bare_operand(next)) {
    lexer->result_symbol = BARE_OPERAND;
    return true;
  }
  return false;
}
